	/** 
	 * jumpstart the process by instantiating2 Agent
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		agentId = AgentService.getAgentInstance()
		.createAgent( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AgentService.getAgentInstance()
				.createAgent( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.agentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Agent : " + successValue.getAgentId());
							  if (successValue.getAgentId().equals(agentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAgentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Agent test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on agent consumed")
					);
			subscriber.agentSubscribe( agentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Agent : " + successValue.getAgentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAgentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on agent for agentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Agent. 
	 */
	protected Agent read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Agent" );

		Agent entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Agent with primary key" );
		msg.append( agentId );
		
		AgentFetchOneSummary fetchOneSummary = new AgentFetchOneSummary( agentId );

		try {
			entity = AgentService.getAgentInstance().getAgent( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Agent " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Agent.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Agent." );

		StringBuilder msg = new StringBuilder( "Failed to update a Agent : " );        
		Agent entity = read();
		UpdateAgentCommand command = generateUpdateCommand();
		command.setAgentId(entity.getAgentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Agent." );

			// for use later on...
			agentId = entity.getAgentId();

			AgentService proxy = AgentService.getAgentInstance();  

			proxy.updateAgent( command ).get();

			LOGGER.info( "-- Successfully saved Agent - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + agentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Agent.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Agent." );

		Agent entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Agent with id " + agentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Agent with id " + agentId );

			throw e;
		}

		try{
			AgentService.getAgentInstance().delete( new DeleteAgentCommand( entity.getAgentId() ) ).get();
			LOGGER.info( "-- Successfully deleted Agent with id " + agentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Agent with id " + agentId );

			throw e;
		}
	}

	/**
	 * get all Agents.
	 */
	protected List<Agent> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Agents:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Agent : " );        
		List<Agent> collection  = new ArrayList<>();

		try {
			// call the static get method on the AgentService
			collection = AgentService.getAgentInstance().getAllAgent();
			assertNotNull( collection, "An Empty collection of Agent was incorrectly returned.");
			
			// Now print out the values
			Agent entity = null;            
			Iterator<Agent> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAgentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

